while let u = readLine() {
    var x = ArraySlice(String(u))
    var q = 0
    let c = x.count
    if String(x) == String(x.reversed()) {
        print(0)
        continue
    }
    for i in 0 ... c {
        x.append(x.popFirst()!)
        q += 1
        if String(x) == String(x.reversed()) {
            break
        }
    }

    if q % c != 0 && q > c {
        print(-1)
    } else {
        print(q % c)
    }
}
